/* TTF text for the plan theme: stb_truetype bakes each (face, size) once into an 8-bit coverage
 * atlas, then glyphs are alpha-blended onto the canvas. No font file at run time: the HUD's font
 * set (a sans in three weights and a mono in two) is compiled in, third_party/atkinson/hud_fonts.c,
 * generated by tools/gen_hud_fonts.py (Atkinson Hyperlegible Next and Mono). */

#include "draw.h"
#include "../third_party/atkinson/hud_fonts.h"

#if defined(__GNUC__) || defined(__clang__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-function"
#pragma GCC diagnostic ignored "-Wsign-compare"
#pragma GCC diagnostic ignored "-Wunused-parameter"
#pragma GCC diagnostic ignored "-Wmissing-field-initializers"
#endif
#define STB_TRUETYPE_IMPLEMENTATION
#define STBTT_STATIC
#include "../third_party/stb/stb_truetype.h"
#if defined(__GNUC__) || defined(__clang__)
#pragma GCC diagnostic pop
#endif

#include <math.h>
#include <stdlib.h>
#include <string.h>

/* Baked set: ASCII 32..126, then degree, plus-minus, middle dot, multiplication sign. */
#define N_ASCII 95
#define N_GLYPHS (N_ASCII + 4)
static const int EXTRA[4] = { 0xB0, 0xB1, 0xB7, 0xD7 };

static int glyph_index(int cp)
{
    if (cp >= 32 && cp <= 126)
        return cp - 32;
    for (int i = 0; i < 4; i++)
        if (cp == EXTRA[i])
            return N_ASCII + i;
    return '?' - 32;
}

static const unsigned char *face_data(int font)
{
    return font == DRAW_FONT_SANS_MEDIUM     ? hud_font_sans_medium
           : font == DRAW_FONT_SANS_SEMIBOLD ? hud_font_sans_semibold
           : font == DRAW_FONT_MONO          ? hud_font_mono
           : font == DRAW_FONT_MONO_REGULAR  ? hud_font_mono_regular
                                             : hud_font_sans_regular;
}

static stbtt_fontinfo g_info[DRAW_FONT_N];
static int g_info_ok[DRAW_FONT_N] = { -1, -1, -1, -1, -1 };

static const stbtt_fontinfo *face(int font)
{
    if (font < 0 || font >= DRAW_FONT_N)
        font = DRAW_FONT_SANS;
    if (g_info_ok[font] < 0) {
        const unsigned char *d = face_data(font);
        g_info_ok[font] = stbtt_InitFont(&g_info[font], d, stbtt_GetFontOffsetForIndex(d, 0)) ? 1 : 0;
    }
    return g_info_ok[font] ? &g_info[font] : NULL;
}

typedef struct {
    int px, font;
    unsigned char *atlas;
    int aw, ah;
    stbtt_packedchar ch[N_GLYPHS];
    int codepoint[N_GLYPHS];
} baked;

#define N_BAKED 16
static baked g_baked[N_BAKED];
static int g_n_baked;

static const baked *bake(int px, int font)
{
    if (font < 0 || font >= DRAW_FONT_N)
        font = DRAW_FONT_SANS;
    if (px < 6)
        px = 6;
    if (px > 96)
        px = 96;
    for (int i = 0; i < g_n_baked; i++)
        if (g_baked[i].px == px && g_baked[i].font == font)
            return g_baked[i].atlas ? &g_baked[i] : NULL;
    baked *b = &g_baked[g_n_baked < N_BAKED ? g_n_baked++ : N_BAKED - 1];
    free(b->atlas);
    memset(b, 0, sizeof *b);
    b->px = px;
    b->font = font;
    for (int k = 0; k < N_ASCII; k++)
        b->codepoint[k] = 32 + k;
    for (int k = 0; k < 4; k++)
        b->codepoint[N_ASCII + k] = EXTRA[k];
    for (int side = 256; side <= 2048; side *= 2) {
        b->aw = b->ah = side;
        b->atlas = calloc((size_t)side * (size_t)side, 1);
        if (!b->atlas)
            return NULL;
        stbtt_pack_context pc;
        stbtt_pack_range rg;
        memset(&rg, 0, sizeof rg);
        rg.font_size = STBTT_POINT_SIZE((float)px); /* em size, like CSS font-size */
        rg.array_of_unicode_codepoints = b->codepoint;
        rg.num_chars = N_GLYPHS;
        rg.chardata_for_range = b->ch;
        int ok = stbtt_PackBegin(&pc, b->atlas, side, side, 0, 1, NULL);
        if (ok) {
            stbtt_PackSetOversampling(&pc, 1, 1);
            ok = stbtt_PackFontRanges(&pc, face_data(font), 0, &rg, 1);
            stbtt_PackEnd(&pc);
        }
        if (ok)
            return b;
        free(b->atlas);
        b->atlas = NULL;
    }
    return NULL;
}

void draw_ui_init(int canvas_h)
{
    /* The plan theme's sizes at a 720 px tall canvas (plan.h), scaled to this one. */
    float u = canvas_h > 0 ? (float)canvas_h / 720.0f : 1.0f;
    static const int sizes[][2] = { { DRAW_FONT_SANS_SEMIBOLD, 19 }, { DRAW_FONT_SANS_SEMIBOLD, 14 },
                                    { DRAW_FONT_SANS_MEDIUM, 13 },   { DRAW_FONT_MONO, 15 },
                                    { DRAW_FONT_MONO, 13 },          { DRAW_FONT_MONO_REGULAR, 11 } };
    for (size_t i = 0; i < sizeof sizes / sizeof sizes[0]; i++)
        bake((int)lroundf((float)sizes[i][1] * u), sizes[i][0]);
}

/* Next code point of a UTF-8 string (2-byte sequences are enough here). */
static int next_cp(const char **s)
{
    const unsigned char *p = (const unsigned char *)*s;
    int cp = *p++;
    if (cp >= 0xC0 && cp < 0xE0 && (*p & 0xC0) == 0x80)
        cp = ((cp & 0x1F) << 6) | (*p++ & 0x3F);
    else if (cp >= 0x80)
        cp = '?';
    *s = (const char *)p;
    return cp;
}

static float kern(int font, int px, int a, int b)
{
    const stbtt_fontinfo *f = face(font);
    if (!f || !a || !b)
        return 0;
    return (float)stbtt_GetCodepointKernAdvance(f, a, b) * stbtt_ScaleForMappingEmToPixels(f, (float)px);
}

int draw_ui_width(int px, int font, const char *s)
{
    const baked *b = bake(px, font);
    if (!b || !s)
        return 0;
    float x = 0;
    int prev = 0;
    while (*s) {
        int cp = next_cp(&s);
        x += kern(b->font, b->px, prev, cp) + b->ch[glyph_index(cp)].xadvance;
        prev = cp;
    }
    return (int)ceilf(x);
}

int draw_ui_cap(int px, int font)
{
    const stbtt_fontinfo *f = face(font);
    int x0, y0, x1, y1;
    if (!f || !stbtt_GetCodepointBox(f, 'H', &x0, &y0, &x1, &y1))
        return (int)lroundf(0.7f * (float)px);
    return (int)lroundf((float)y1 * stbtt_ScaleForMappingEmToPixels(f, (float)px));
}

int draw_ui_text(canvas *c, int x, int baseline, int px, int font, uint32_t col, int alpha,
                 const char *s)
{
    const baked *b = bake(px, font);
    if (!b || !s)
        return x;
    float pen = (float)x;
    int prev = 0;
    while (*s) {
        int cp = next_cp(&s);
        const stbtt_packedchar *g = &b->ch[glyph_index(cp)];
        pen += kern(b->font, b->px, prev, cp);
        prev = cp;
        int gx = (int)lroundf(pen + g->xoff), gy = baseline + (int)lroundf(g->yoff);
        int gw = g->x1 - g->x0, gh = g->y1 - g->y0;
        for (int j = 0; j < gh; j++) {
            int yy = gy + j;
            if ((unsigned)yy >= (unsigned)c->h)
                continue;
            const unsigned char *row = b->atlas + (size_t)(g->y0 + j) * (size_t)b->aw + g->x0;
            uint32_t *dst = c->px + (size_t)yy * (size_t)c->stride;
            for (int i = 0; i < gw; i++) {
                int xx = gx + i;
                if (!row[i] || (unsigned)xx >= (unsigned)c->w)
                    continue;
                dst[xx] = draw_mix(dst[xx], col, row[i] * alpha / 255);
            }
        }
        pen += g->xadvance;
    }
    return (int)ceilf(pen);
}

int draw_ui_text_top(canvas *c, int x, int y, int px, int font, uint32_t col, int alpha,
                     const char *s)
{
    const stbtt_fontinfo *f = face(font);
    int asc = 0, desc = 0, gap = 0;
    float sc = f ? stbtt_ScaleForMappingEmToPixels(f, (float)px) : 0;
    if (f)
        stbtt_GetFontVMetrics(f, &asc, &desc, &gap);
    /* Em box top: the ascender share of one em (ascent / (ascent - descent)). */
    float top = f && asc - desc > 0 ? (float)px * (float)asc / (float)(asc - desc) : 0.8f * (float)px;
    (void)sc;
    return draw_ui_text(c, x, y + (int)lroundf(top), px, font, col, alpha, s);
}
